class Course
{
    public required string Name { get; init; }
    public int PassMark { get; }

    public Course(int passMark)
    {
        if (passMark is < 0 or > 100)
            throw new ArgumentOutOfRangeException(nameof(passMark));

        PassMark = passMark;
    }
}

Course course = new(80) { Name = "C# Junior" };
Console.WriteLine(course.PassMark);

