interface IScorable
{
    int Score { get; }
    bool Passed(int passMark);
}

class Assessment : IScorable
{
    public int Score { get; init; }
    public bool Passed(int passMark) => Score >= passMark;
}

IScorable result = new Assessment { Score = 91 };
Console.WriteLine(result.Passed(80));

